  "Agent updates are simulated in this preview.": "Agenten-Updates werden in dieser Vorschau simuliert.",
  "Agent → business transfer": "Überweisung an das Unternehmen",
  "Agents": "Vertriebspartner",
  "Agents & agreements": "Vertriebspartner und Vereinbarungen",
  "Agents can record an order and share it in chat to request a correction. Admin corrections must preserve history and update stock and financial totals together.": "Vertriebspartner können Bestellungen erfassen und im Chat eine Korrektur anfordern. Die Administration muss dabei den bisherigen Verlauf erhalten und Bestand sowie Finanzsummen gemeinsam aktualisieren.",
  "Agents get one notification. Earlier versions stay in history.": "Agenten erhalten eine Benachrichtigung. Frühere Versionen bleiben in der Geschichte.",
  "Agents keep their commission and send the remainder. A transfer clears only its included orders after admin confirmation. New sales and pending transfers stay separate.": "Vertriebspartner behalten ihre Provision und überweisen den Restbetrag. Erst die Bestätigung durch die Administration rechnet die in der Überweisung enthaltenen Bestellungen ab. Neue Verkäufe und ausstehende Überweisungen bleiben separat.",
  "Agents lose access to every version of the product protocol at once: the library, and links already shared in chats (the chat cards stay, marked unavailable). The editable source stays here as a draft and its history is kept. Publishing again continues the version numbers.": "Vertriebspartner verlieren sofort den Zugriff auf alle Versionen dieses Produktprotokolls, sowohl in der Bibliothek als auch über bereits im Chat geteilte Links. Die Chatkarten bleiben mit dem Hinweis „Nicht verfügbar“ sichtbar. Bearbeitbare Quelle und Versionsverlauf bleiben als Entwurf erhalten. Bei erneuter Veröffentlichung läuft die Versionsnummerierung weiter.",
  "Agents lose access to every version of this product's protocol at once: the library, and links already shared in chats (the chat cards stay, marked unavailable). The editable source stays here as a draft and its history is kept. Publishing again continues the version numbers.": "Vertriebspartner verlieren sofort den Zugriff auf alle Versionen dieses Produktprotokolls, sowohl in der Bibliothek als auch über bereits im Chat geteilte Links. Die Chatkarten bleiben mit dem Hinweis „Nicht verfügbar“ sichtbar. Bearbeitbare Quelle und Versionsverlauf bleiben als Entwurf erhalten. Bei erneuter Veröffentlichung läuft die Versionsnummerierung weiter.",
  "Agents lose access to every version of this protocol at once: the library, and also links already shared in chats (the chat cards stay, marked unavailable). Admins keep the history. You can restore it later.": "Vertriebspartner verlieren sofort den Zugriff auf alle Versionen dieses Protokolls in der Bibliothek und über bereits im Chat geteilte Links. Die Chatkarten bleiben mit dem Hinweis „Nicht verfügbar“ sichtbar. Die Administration behält den Verlauf und kann das Protokoll später wiederherstellen.",
  "Agents may apply an order-specific discount or free item, with a reason and note. Original assigned prices stay visible. Free items reduce stock and business profit, and earn no commission.": "Vertriebspartner können einer Bestellung mit Begründung und Notiz einen Rabatt oder Gratisartikel hinzufügen. Die ursprünglich zugewiesenen Preise bleiben sichtbar. Gratisartikel verringern Bestand und Unternehmensgewinn. Für sie fällt keine Provision an.",
  "Agents overview": "Vertriebspartner im Überblick",
  "Agents retain commission and send the business share. Admin confirms receipt against included sales.": "Vertriebspartner behalten ihre Provision und überweisen den Unternehmensanteil. Die Administration gleicht den Zahlungseingang mit den zugehörigen Verkäufen ab und bestätigt ihn.",
  "Agents should be offered this batch from now on.": "Agenten sollte diese Charge von nun an angeboten werden.",
  "Agents switch to this version. The previous version stays in version history.": "Agenten wechseln zu dieser Version. Die vorherige Version bleibt in der Versionshistorie.",
  "Agents will be able to view and download this protocol.": "Vertriebspartner können dieses Protokoll ansehen und herunterladen.",
  "Agents will be offered": "Für Vertriebspartner verfügbar",
  "Agents will no longer be able to open it here. A replacement can be uploaded later.": "Vertriebspartner können das Dokument hier nicht mehr öffnen. Später können Sie einen Ersatz hochladen.",
  "Agents will see an update in their notifications.": "Vertriebspartner erhalten eine Benachrichtigung zur Änderung.",
