  "Available stock held by commission accounts, partners and your own shop, plus their sales not yet settled. Supplier stock and prepaid wholesale resales are excluded. Confirming a transfer clears only its included sales.": "Verfügbarer Warenbestand bei Provisionskonten, Partnern und im eigenen Shop, zuzüglich noch abzurechnender Verkäufe. Lieferantenbestände und Weiterverkäufe von im Voraus bezahlter Großhandelsware sind ausgenommen. Mit der Bestätigung einer Überweisung werden nur die zugehörigen Verkäufe abgerechnet.",
