  "Batch reference": "Chargenreferenz",
  "Batch-specific protocols are not attached: sold stock has no batch reference to match them (owner decision PROTO-BATCH).": "Chargenspezifische Protokolle werden nicht angehängt, weil für die verkaufte Ware keine passende Chargenreferenz vorliegt (Entscheidung des Inhabers PROTO-BATCH).",
