  "Being prepared": "zubereitet werden",
  "Belongs to": "gehört zu",
  "Below product cost · the difference is recorded in business profit.": "Unterhalb der Produktkosten · Die Differenz wird im Geschäftsgewinn erfasst.",
  "Blocked (default)": "Blockiert (Standard)",
  "Blocked in the browser": "Im Browser blockiert",
  "Blue is available stock value. Purple is sales not yet settled.": "Blau zeigt den Wert der verfügbaren Ware, Violett die noch abzurechnenden Verkäufe.",
  "Blue is unsold stock held by commission agents and partners, valued at current selling prices. Purple is their recorded sales awaiting settlement, including pending transfers and unpaid customer sales. It shows gross sale value, not commission or the net transfer amount. Only confirming a transfer removes its included sales; new sales and physical stock remain. Warehouse stock and prepaid wholesale accounts are excluded. This current balance does not change with the report date filter.": "Blau zeigt die unverkaufte Ware bei Vertriebspartnern auf Provisionsbasis und bei Partnern, bewertet zu aktuellen Verkaufspreisen. Violett zeigt den Bruttowert ihrer noch abzurechnenden Verkäufe, einschließlich ausstehender Überweisungen und offener Kundenzahlungen. Provision und Nettoüberweisungsbetrag werden hier nicht dargestellt. Die Bestätigung einer Überweisung bucht nur die zugehörigen Verkäufe aus. Neue Verkäufe und Warenbestände bleiben erhalten. Lagerbestände und Vorkasse-Großhandelskonten sind ausgenommen. Der Datumsfilter hat keinen Einfluss auf diesen aktuellen Saldo.",
  "Blue shows unsold stock held by commission agents and partners at its assigned selling prices. Purple shows their sales not yet settled, including unpaid sales and pending transfers. Confirming a transfer removes only its included sales. Warehouse stock and prepaid wholesale accounts are excluded. This balance is independent of report dates.": "Blau zeigt die unverkaufte Ware bei Vertriebspartnern auf Provisionsbasis und bei Partnern, bewertet zu den zugewiesenen Verkaufspreisen. Violett zeigt die noch abzurechnenden Verkäufe einschließlich offener Kundenzahlungen und ausstehender Überweisungen. Mit der Bestätigung einer Überweisung werden nur die zugehörigen Verkäufe ausgebucht. Lagerbestände und Vorkasse-Großhandelskonten sind ausgenommen. Der Berichtszeitraum hat keinen Einfluss auf den Saldo.",
  "Booked": "Verbucht",
  "Booked amount": "Verbuchter Betrag",
