  "Commission agent · % of profit": "Vertriebspartner · Gewinnprovision",
  "Commission agents earn a percentage of profit after costs. Partners earn a percentage of the actual sale amount. Prepaid wholesale buyers track resales without new commission or debt.": "Vertriebspartner auf Provisionsbasis erhalten einen Anteil am Gewinn nach Abzug der Kosten. Partner erhalten einen Anteil am tatsächlichen Verkaufserlös. Großhandelskäufer mit Vorkasse erfassen ihre Weiterverkäufe ohne zusätzliche Provision oder Verbindlichkeit.",
