  "Commission breakdown": "Provisionsaufstellung",
  "Commission calculation": "Berechnung der Kommission",
  "Commission is rounded once per order; cents are assigned by largest remainder. Free items earn no commission. Their cost reduces business profit.": "Die Provision wird einmal je Bestellung gerundet. Verbleibende Centbeträge werden den Positionen mit den größten Rundungsresten zugeordnet. Für Gratisartikel fällt keine Provision an. Ihre Kosten mindern den Unternehmensgewinn.",
