  "Compare what agents still need to send, what is awaiting confirmation and what has been received. These are current balances, independent of the selected report dates.": "Vergleichen Sie offene Beträge der Vertriebspartner, gemeldete Überweisungen mit ausstehender Bestätigung und bestätigte Zahlungseingänge. Die aktuellen Salden sind vom gewählten Berichtszeitraum unabhängig.",
  "Compares the same elapsed part of the previous period. For example, Monday to Wednesday this week is compared with Monday to Wednesday last week. Today stops at the same time of day in both periods.": "Vergleicht den gleichen verstrichenen Teil der vorherigen Periode. Zum Beispiel wird Montag bis Mittwoch diese Woche mit Montag bis Mittwoch letzte Woche verglichen. Heute stoppt zur gleichen Tageszeit in beiden Perioden.",
