  "Creates a draft. When sending from an account's stock, saving reserves those units so they can't be sold meanwhile. Nothing leaves stock until you press Send.": "Erstellt einen Entwurf. Beim Versand aus einem Bestandskonto reserviert das Speichern die Einheiten. Sie können bis dahin nicht anderweitig verkauft werden. Erst mit „Senden“ wird der Bestand ausgebucht.",
  "Creates the catalogue product only: no stock, purchase, order or revenue. Prices apply to future shipments.": "Erstellt ausschließlich das Katalogprodukt. Dabei werden weder Bestand noch Einkauf, Bestellung oder Umsatz gebucht. Die Preise gelten für künftige Sendungen.",
  "Currency": "Währung",
  "Currency is fixed after creation. Assign prices before using this list.": "Nach dem Anlegen ist die Währung festgelegt. Hinterlegen Sie die Preise, bevor Sie die Liste verwenden.",
