  "Discounts & free items": "Rabatte & kostenlose Artikel",
  "Discounts and free items": "Rabatte und kostenlose Artikel",
  "Discounts compare the original price with the actual paid price. Free items are counted separately at their original value and actual product cost. Free items do not reduce the commission on paid items, but their cost reduces business profit. These figures describe recorded orders, not revenue that was guaranteed. Prepaid wholesale accounts show their resale activity here; those resales do not count again as business revenue. No automatic limits or agent charges are applied.": "Der Rabatt ergibt sich aus der Differenz zwischen ursprünglichem und bezahltem Preis. Gratisartikel werden separat mit ihrem ursprünglichen Wert und den tatsächlichen Produktkosten ausgewiesen. Ihre Kosten mindern den Unternehmensgewinn. Die Provision auf bezahlte Artikel bleibt gleich. Die Zahlen beziehen sich auf erfasste Bestellungen und stellen keine Umsatzgarantie dar. Auch Weiterverkäufe von Großhandelskäufern mit Vorkasse sind hier sichtbar. Sie werden nicht erneut als Unternehmensumsatz gezählt. Es gelten keine automatischen Obergrenzen oder Gebühren für Vertriebspartner.",
