  "Drafts are saved on the server. Saving or previewing never changes what agents see; publishing does, after confirmation.": "Entwürfe werden auf dem Server gespeichert. Speichern und Vorschau ändern die Ansicht der Vertriebspartner nicht. Erst die bestätigte Veröffentlichung macht Änderungen sichtbar.",
