  "Duplicated as a new unassigned draft.": "Dupliziert als neuer, nicht zugewiesener Entwurf.",
  "ENABLE": "ENABLE",
  "EUR per": "EUR pro Stück",
  "EUR per 1 unit of currency": "EUR je 1 Währungseinheit",
  "EUR · saved batch prices": "EUR · gesparte Chargenpreise",
  "EUR, the ledger currency. The wholesale price is what the buyer pays the business; it is not the supplier's landed cost or the buyer's resale price. A draft can be changed until it is issued.": "Die Buchungswährung ist EUR. Der Großhandelspreis ist der Betrag, den der Käufer an das Unternehmen zahlt. Die Einstandskosten des Lieferanten und der spätere Wiederverkaufspreis des Käufers sind davon unabhängig. Bis zur Ausstellung kann der Entwurf bearbeitet werden.",
  "EUR. Buyer credits are not supported.": "EUR. Käuferkredite werden nicht unterstützt.",
  "EUR. Supplier credits/advances are not enabled.": "EUR. Lieferantenkredite/-vorschüsse sind nicht aktiviert.",
  "Each charge needs a label and an amount.": "Jede Ladung benötigt ein Etikett und einen Betrag.",
  "Each checkout once": "Jeder Checkout einmal",
  "Each choice must be on or off.": "Jede Wahl muss ein- oder ausgeschaltet sein.",
  "Each file is limited to 20 MB.": "Jede Datei ist auf 20 MB begrenzt.",
  "Each file must be 20 MB or smaller.": "Jede Datei muss 20 MB oder kleiner sein.",
  "Each line needs a unique position.": "Jede Zeile benötigt eine eindeutige Positionsnummer.",
  "Each line needs whole units and the supplier invoice total.": "Jede Zeile benötigt ganze Einheiten und die Lieferantenrechnung insgesamt.",
  "Each line needs whole units, a total cost, a selling price and a received date.": "Jede Linie benötigt ganze Einheiten, einen Gesamtpreis, einen Verkaufspreis und ein erhaltenes Datum.",
  "Each line needs whole units, a unit price and an optional discount with at most two decimals.": "Jede Zeile benötigt ganze Einheiten, einen Stückpreis und einen optionalen Rabatt mit höchstens zwei Dezimalstellen.",
  "Each message expires one calendar month after it was sent (workspace time zone": "Jede Nachricht läuft einen Kalendermonat nach dem Senden ab (Workspace-Zeitzone)",
  "Each message expires one calendar month after it was sent.": "Jede Nachricht läuft einen Kalendermonat nach dem Versand ab.",
  "Each product appears once per invoice. Combine the quantities.": "Jedes Produkt erscheint einmal pro Rechnung. Kombination der Mengen.",
  "Each product appears once per purchase.": "Jedes Produkt erscheint einmal pro Kauf.",
  "Each product can appear once.": "Jedes Produkt kann einmal erscheinen.",
  "Each product of a buyer shipment must come from a line of the wholesale sale.": "Jedes Produkt einer Käufersendung muss aus einer Linie des Großhandelsverkaufs stammen.",
  "Each received batch keeps its cost and selling price. Oldest stock sells first; a new dispatch can use new prices without changing existing stock.": "Für jede eingegangene Charge bleiben Einstandskosten und Verkaufspreis gespeichert. Die älteste verfügbare Charge wird zuerst verkauft. Für neue Sendungen lassen sich eigene Preise festlegen.",
  "Each received batch keeps its own selling price and cost. Oldest batches sell first.": "Jede erhaltene Charge behält ihren eigenen Verkaufspreis und Kosten. Älteste Chargen verkaufen sich zuerst.",
  "Each shipment line appears once in a correction.": "Jede Sendungslinie erscheint einmal in einer Korrektur.",
  "Each transfer keeps its original included sales, commission and payment reference. Confirming one transfer never clears newer sales.": "Für jede Überweisung bleiben die ursprünglich zugeordneten Verkäufe, Provisionen und die Zahlungsreferenz gespeichert. Bei der Bestätigung werden neuere Verkäufe nicht mit abgerechnet.",
