  "Every damaged unit on this line already has a recorded decision.": "Jede beschädigte Einheit auf dieser Linie hat bereits eine aufgezeichnete Entscheidung.",
  "Every protocol uses the same premium light template for text, tables and pictures. Save draft keeps unfinished changes separate from the published PDF. Duplicate creates a saved, unassigned draft. Preview generates Word and PDF. Publish updates only the selected product after confirmation and keeps its previous version in history.": "Alle Protokolle verwenden dieselbe helle Vorlage für Texte, Tabellen und Bilder. „Entwurf speichern“ hält Änderungen getrennt vom veröffentlichten PDF. „Duplizieren“ erstellt einen gespeicherten Entwurf ohne Produktzuordnung. Die Vorschau erzeugt Word- und PDF-Dateien. Erst die bestätigte Veröffentlichung aktualisiert das gewählte Produkt. Die vorherige Version bleibt im Verlauf erhalten.",
  "Every requested unit is already planned in a shipment.": "Alle angeforderten Einheiten sind bereits für eine Sendung eingeplant.",
  "Every shipment. Its own costs. A clear trail.": "Jede Lieferung. Ihre eigenen Kosten. Ein klarer Weg.",
  "Everyone": "Alle",
