  "From business stock, saving holds the source units so they cannot be sold meanwhile. Supplier direct uses units of that purchase not yet sent.": "Aus Geschäftsbeständen hält das Sparen die Quelleinheiten, so dass sie zwischenzeitlich nicht verkauft werden können. Der Lieferant verwendet direkt Einheiten dieses Kaufs, die noch nicht gesendet wurden.",
