  "Full access covers all operational areas, including financial data and workspace settings. Custom access includes only the selected areas. Only Super admins manage the admin team. Manage includes View; no access means the area is unavailable.": "Vollzugriff umfasst alle betrieblichen Bereiche einschließlich Finanzdaten und Arbeitsbereichseinstellungen. Individueller Zugriff gilt nur für ausgewählte Bereiche. Das Admin-Team dürfen ausschließlich Super-Admins verwalten. Verwaltungsrechte schließen Leserechte ein. Ohne Berechtigung ist der Bereich gesperrt.",
