  "German edition of one exact English revision. The product and batch stay fixed. Publishing makes the reviewed German PDF available alongside English; a new English revision needs a new German review.": "Diese deutsche Fassung gehört zu einer bestimmten englischen Version. Produkt und Charge sind fest zugeordnet. Nach der Freigabe sind beide Sprachen verfügbar. Eine neue englische Version erfordert eine erneute Prüfung der Übersetzung.",
