  "Held for a draft shipment": "Halten für einen Entwurf der Verbringung",
  "Hello": "Hallo",
  "Here are the protocol documents for your order. They are attached to this email as PDF files.": "Im Anhang dieser E-Mail finden Sie die Protokolle zu Ihrer Bestellung als PDF-Dateien.",
  "Here are the uploaded protocol documents for your order. Contact your agent if a document is missing or does not match your item.": "Hier finden Sie die hochgeladenen Protokolle zu Ihrer Bestellung. Wenden Sie sich an Ihren Vertriebspartner, wenn ein Dokument fehlt oder nicht zum bestellten Artikel passt.",
  "Hi Maria. You can contact our team here about your stock, transfers or protocols.": "Hi Maria. Sie können sich hier mit unserem Team über Ihre Bestände, Überweisungen oder Protokolle in Verbindung setzen.",
  "Hidden": "Ausgeblendet",
  "Hides it from the active catalogue. Existing stock, shipments, orders, prices and protocols are kept and stay usable.": "Verbirgt es aus dem aktiven Katalog. Vorhandene Bestände, Sendungen, Bestellungen, Preise und Protokolle werden aufbewahrt und bleiben nutzbar.",
