  "Holds keep units for a draft shipment without moving them. Only movements change the remaining quantity.": "Eine Reservierung hält Einheiten für einen Versandentwurf frei. Erst eine Warenbewegung ändert die Restmenge.",
  "Home": "Startseite",
  "Hormonal research": "Hormonelle Forschung",
  "How can I help?": "Wie kann ich helfen?",
  "How collected sales split into your commission and the amount owed to the business. Pending and confirmed transfers are shown separately.": "So verteilen sich kassierte Verkaufserlöse auf Ihre Provision und den an das Unternehmen zu zahlenden Betrag. Ausstehende und bestätigte Überweisungen sind getrennt ausgewiesen.",
  "How costs are allocated": "Wie die Kosten aufgeteilt werden",
