  "I checked the content, strength and source notes.": "Ich habe den Inhalt, die Stärke und die Quellen überprüft.",
  "I confirm that I am": "Ich bestätige, dass ich",
  "I received": "Ich erhielt",
  "I reviewed this German file against the published English revision.": "Ich habe die deutsche Datei mit der veröffentlichten englischen Fassung abgeglichen.",
  "I sent request": "Ich habe eine Anfrage gesendet",
  "I will pay when I collect.": "Ich werde bezahlen, wenn ich sammle.",
  "If an account exists for that email, we will email a reset link. It works for one hour. If nothing arrives within a few minutes, check spam or ask your workspace admin.": "Wenn ein Konto für diese E-Mail existiert, werden wir einen Reset-Link per E-Mail senden. Es funktioniert eine Stunde lang. Wenn nichts innerhalb weniger Minuten eintrifft, überprüfen Sie Spam oder fragen Sie Ihren Workspace-Admin.",
  "If the address has an account, we email a link that works for one hour.": "Falls zu dieser Adresse ein Konto besteht, senden wir per E-Mail einen Link, der eine Stunde lang gültig ist.",
  "If this email has a conversation with this shop, a sign-in link is on its way. It works once and expires soon.": "Wenn diese E-Mail ein Gespräch mit diesem Shop hat, ist ein Anmeldelink auf dem Weg. Es funktioniert einmal und läuft bald ab.",
