  "Imported sources start as review drafts. Manual PDF uploads remain PDF-only. This preview saves on your device; the backend storage and notifications still need implementation.": "Importierte Quellen beginnen als Review-Entwürfe. Manuelle PDF-Uploads bleiben PDF-only. Diese Vorschau speichert auf Ihrem Gerät; der Backend-Speicher und die Benachrichtigungen müssen noch implementiert werden.",
