  "Latest available daily reference data, not a real-time trading quote. The published rate date is shown. Weekends and holidays can have an earlier date. Failed refreshes retain the last rate with a warning. Historical batches keep their recorded conversion rate.": "Angezeigt wird der zuletzt veröffentlichte Tagesreferenzkurs mit Kursdatum. An Wochenenden und Feiertagen kann er von einem früheren Tag stammen. Bei einem Aktualisierungsfehler bleibt der letzte Kurs mit einem Hinweis sichtbar. Bestehende Chargen behalten ihren erfassten Umrechnungskurs. Es handelt sich um keinen Echtzeitkurs.",
