  "Low-stock threshold must be a whole number from 0 to 100,000.": "Low-Stock-Schwelle muss eine ganze Zahl von 0 bis 100.000 sein.",
  "Lower a quantity or enter 0 to remove an incorrect item. Removed units return to stock. Original prices and costs stay unchanged. Record additional units as a new sale. For an actual refund or returned product, reconcile the customer's money separately.": "Verringern Sie die Menge oder geben Sie 0 ein, um einen falschen Artikel zu entfernen. Entfernte Einheiten werden dem Bestand wieder zugebucht. Die ursprünglichen Preise und Kosten bleiben erhalten. Zusätzliche Einheiten sind als neuer Verkauf zu erfassen. Gleichen Sie tatsächliche Rückerstattungen oder Warenrückgaben separat mit der Kundenzahlung ab.",
  "MB and cannot be attached. Share it another way.": "MB und kann nicht angehängt werden. Teilen Sie es auf eine andere Weise.",
