  "Plan now": "Planen Sie jetzt",
  "Plan starting stock for this account. Stock becomes usable only after the person confirms the delivery. You can also do this later from the account page.": "Planen Sie den Anfangsbestand für dieses Konto. Die Ware wird erst mit der Empfangsbestätigung verfügbar. Sie können das auch später auf der Kontoseite erledigen.",
  "Planned": "Geplant",
  "Planned and sent quantities count toward the request. Requested and draft quantities never create stock.": "Geplante und versandte Mengen werden auf die Anfrage angerechnet. Eine Anfrage oder ein Entwurf allein erhöht den Bestand nicht.",
  "Planned request quantities are released for another shipment.": "Geplante Anforderungsmengen werden für eine weitere Lieferung freigegeben.",
  "Planned vials": "Geplante Vials",
  "Planned wholesale dispatches can no longer be sent. Already recognised sales stay recorded.": "Geplante Großhandelssendungen können nicht mehr versandt werden. Bereits erfasste Umsätze bleiben verbucht.",
  "Planned wholesale dispatches can then be sent. Stock becomes the buyer’s, and the sale counts as wholesale revenue, when the buyer confirms usable units after full payment. This is the proposed convention, not an approved owner decision.": "Anschließend können geplante Großhandelssendungen versandt werden. Nach vollständiger Zahlung gehen die verwendbaren Einheiten mit der Empfangsbestätigung in das Eigentum des Käufers über. Dann wird der Großhandelsumsatz erfasst. Diese Regel ist ein Vorschlag. Die Freigabe durch den Inhaber steht noch aus.",
  "Please confirm that you are 18 or older.": "Bitte bestätigen Sie, dass Sie 18 Jahre oder älter sind.",
  "Please contact your agent directly.": "Wenden Sie sich direkt an Ihren Vertriebspartner.",
  "Please fill in this field.": "Bitte füllen Sie dieses Feld aus.",
  "Please let me know when collection is possible.": "Bitte lassen Sie mich wissen, wann die Sammlung möglich ist.",
  "Please replenish stock for next week.": "Bitte füllen Sie den Vorrat für die nächste Woche auf.",
  "Please sign in again.": "Bitte melden Sie sich erneut an.",
  "Possible only while nothing from this purchase was sent, planned on a shipment or paid. Its payables close and any fee booked as an expense is reversed in its own period. The purchase stays visible as cancelled.": "Eine Stornierung ist nur möglich, solange nichts aus diesem Einkauf versandt, für eine Sendung eingeplant oder bezahlt wurde. Offene Verbindlichkeiten werden geschlossen. Als Aufwand gebuchte Gebühren werden in ihrer ursprünglichen Periode storniert. Der Einkauf bleibt als storniert sichtbar.",
  "Possible while no payment is recorded and no dispatch is planned. The invoice stays visible as cancelled.": "Eine Stornierung ist möglich, solange keine Zahlung erfasst und kein Versand geplant ist. Die Rechnung bleibt als storniert sichtbar.",
