  "Received batch prices are fixed. Set new prices on a new dispatch; existing stock keeps its original prices.": "Die erhaltenen Chargenpreise sind festgelegt. Legen Sie neue Preise für einen neuen Versand fest; der vorhandene Bestand behält seine ursprünglichen Preise.",
