  "Received in usable condition": "Empfangen in nutzbarem Zustand",
  "Received means the total physically received, including any damaged units. Only undamaged units become available.": "Als eingegangen zählt die gesamte tatsächlich erhaltene Menge einschließlich beschädigter Einheiten. Nur unbeschädigte Einheiten werden verfügbar.",
  "Received must be a whole quantity within sent stock; damaged cannot exceed received.": "Die eingegangene Menge muss ganzzahlig sein und darf die versandte Menge nicht übersteigen. Es können höchstens so viele Einheiten beschädigt sein, wie eingegangen sind.",
