  "Record and select a supplier-direct purchase for this agent first.": "Notieren und wählen Sie zuerst einen direkten Lieferantenkauf für diesen Agenten aus.",
  "Record arrival": "Wareneingang erfassen",
  "Record correction": "Korrektur erfassen",
  "Record customer payment": "Kundenzahlung erfassen",
  "Record each supplier order at its landed cost. Opening stock is a starting balance, not a new purchase or money spent. Payments are recorded separately after you have paid the supplier.": "Erfassen Sie jede Lieferantenbestellung zu ihren Einstandskosten. Der Anfangsbestand wird als Ausgangswert erfasst, ohne neuen Einkauf oder Geldabfluss. Lieferantenzahlungen werden nach der tatsächlichen Zahlung separat gebucht.",
  "Record late arrival": "Verspäteten Wareneingang erfassen",
  "Record late arrival ·": "Verspäteten Wareneingang erfassen ·",
  "Record money you have already paid to this supplier. This form records the payment; it does not send money.": "Erfassen Sie bereits an diesen Lieferanten gezahlte Beträge. Dieses Formular dokumentiert die Zahlung und führt keine Überweisung aus.",
