  "Record voice message": "Sprachnachricht aufnehmen",
  "Record what you corrected or checked. This is your review, not an AI or medical verification.": "Halten Sie fest, was Sie geprüft oder korrigiert haben. Dies ist Ihre eigene Prüfung. Es erfolgt weder eine KI-Prüfung noch eine medizinische Verifizierung.",
  "Record what you corrected or checked. This is your review, not an AI or medical verification. Editing the content later reopens the note.": "Halten Sie fest, was Sie geprüft oder korrigiert haben. Dies ist Ihre eigene Prüfung. Es erfolgt weder eine KI-Prüfung noch eine medizinische Verifizierung. Bei späteren Änderungen am Inhalt wird der Vermerk erneut zur Prüfung geöffnet.",
  "Recorded": "Erfasst",
  "Recorded after this count, dated before it": "Aufgenommen nach dieser Zählung, datiert davor",
