  "Recorded landed product costs": "Erfasste Einstandskosten der Produkte",
  "Recorded payments will appear here.": "Aufgezeichnete Zahlungen werden hier angezeigt.",
  "Recorded running costs kept separate from the landed cost of stock.": "Erfasste laufende Betriebskosten, getrennt von den Einstandskosten der Ware.",
  "Recorded sales": "Erfasste Verkäufe",
  "Recorded sales are split between the landed cost of sold units and gross profit. Cash collection and capital repayment are tracked separately. The daily chart is illustrative sample data.": "Der erfasste Umsatz wird in die Einstandskosten der verkauften Einheiten und den Bruttogewinn aufgeteilt. Zahlungseingänge und Kapitalrückzahlungen werden getrennt erfasst. Das Tagesdiagramm zeigt Beispieldaten.",
