  "Recording": "Aufzeichnung",
  "Recording a payment records money already paid outside the app; it does not send money or receive stock.": "Sie erfassen eine Zahlung, die bereits außerhalb der App erfolgt ist. Die Buchung löst weder eine Überweisung noch einen Wareneingang aus.",
  "Recording failed. Please try again or attach an audio file.": "Aufzeichnung fehlgeschlagen. Bitte versuchen Sie es erneut oder fügen Sie eine Audiodatei an.",
  "Records": "Einträge",
