  "Records behind the figure": "Zugehörige Einträge",
  "Records one sale with exact FIFO batches, as Record sale does. No payment is processed here.": "Erfasst wie „Verkauf erfassen“ genau einen Verkauf mit den zugehörigen FIFO-Chargen. Es wird keine Zahlung verarbeitet.",
  "Records stock that already exists, with its valuation and provenance. It is not a purchase, supplier payment or personal spend.": "Dokumentiert bereits vorhandene Ware mit Bewertung und Herkunft. Dadurch werden weder ein Einkauf noch eine Lieferantenzahlung oder eine private Ausgabe gebucht.",
