  "Sales after that date already use the current terms. Choose a later start.": "Für Verkäufe nach diesem Datum gelten bereits die aktuellen Konditionen. Wählen Sie ein späteres Anfangsdatum.",
  "Sales and profit use the selected dates. Transfer receipts are shown separately and never counted as extra revenue. Confirmation settles only the sales included in a transfer.": "Umsatz und Gewinn beziehen sich auf den gewählten Zeitraum. Eingegangene Überweisungen werden separat ausgewiesen und zählen nicht erneut als Umsatz. Die Bestätigung rechnet nur die zugehörigen Verkäufe ab.",
  "Sales awaiting settlement": "Noch abzurechnende Verkäufe",
  "Sales for this account, including those already settled. Each sale retains its original quantities, prices, costs and commission.": "Alle Verkäufe dieses Kontos einschließlich bereits abgerechneter Verkäufe. Mengen, Preise, Kosten und Provisionen bleiben je Verkauf in ihrer ursprünglichen Höhe gespeichert.",
  "Sales of business stock to prepaid buyers. Not a supplier purchase and not the buyer's own resale.": "Verkäufe aus dem Unternehmensbestand an Käufer mit Vorkasse. Lieferanteneinkäufe und Weiterverkäufe des Käufers werden separat erfasst.",
  "Sales overview": "Verkaufsübersicht",
  "Sales performance": "Verkaufsleistung",
  "Sales period": "Verkaufszeitraum",
  "Sales recorded": "Gebuchte Verkäufe",
  "Sales revenue": "Umsatzerlöse",
  "Sales revenue minus the landed cost of the items sold and the commission agents keep. Other business expenses and tax are not deducted here.": "Vom Umsatz werden die Einstandskosten der verkauften Artikel und die einbehaltenen Provisionen abgezogen. Weitere Betriebsausgaben und Steuern sind unberücksichtigt.",
  "Sales revenue minus the landed cost of the items sold, before agent commission and other business expenses.": "Umsatz abzüglich der Einstandskosten der verkauften Artikel, vor Abzug der Vertriebspartnerprovision und weiterer Betriebsausgaben.",
  "Sales revenue over your selected dates. The comparison line shows the previous matched period, using the same elapsed days and time for an unfinished period.": "Umsatzerlöse über Ihre ausgewählten Termine. Die Vergleichslinie zeigt die vorherige übereinstimmende Periode an, wobei die gleichen verstrichenen Tage und die gleiche Zeit für eine unfertige Periode verwendet werden.",
  "Sales this month": "Verkäufe in diesem Monat",
  "Sales versus cash": "Umsatz und Bargeldeingang",
  "Sales whose customer payment has not been collected. They cannot be included in a transfer yet.": "Verkäufe mit noch offener Kundenzahlung. Sie können noch keiner Überweisung zugeordnet werden.",
  "Same calendar dates, one year earlier": "Gleiche Kalenderdaten, ein Jahr früher",
  "Same count as": "Gleiche Zählung wie",
