  "Save draft keeps unfinished changes separate from the published PDF. Duplicate creates a saved, unassigned draft. Preview generates the actual PDF and editable Word document on the server. Publish updates only the selected product after confirmation and keeps its previous version in history; agents get one notification.": "Save draft hält unfertige Änderungen von der veröffentlichten PDF-Datei getrennt. Duplicate erstellt einen gespeicherten, nicht zugewiesenen Entwurf. Preview generiert das eigentliche PDF- und editierbare Word-Dokument auf dem Server. Aktualisieren Sie nur das ausgewählte Produkt nach der Bestätigung und behält seine vorherige Version in der Geschichte; Agenten erhalten eine Benachrichtigung.",
