  "Secrets, sign-in links and codes are never recorded or shown. Some values need the matching access.": "Geheimnisse, Anmeldelinks und Codes werden nie protokolliert oder angezeigt. Für bestimmte Werte sind die passenden Zugriffsrechte erforderlich.",
