  "Send the first shipment before creating a follow-up.": "Senden Sie die erste Sendung, bevor Sie ein Follow-up erstellen.",
  "Send to": "Senden an",
  "Sending files in private conversations requires Messages Manage.": "Zum Versenden von Dateien in privaten Unterhaltungen benötigen Sie Verwaltungsrechte für Nachrichten.",
  "Sending follows the workspace wholesale policy (G1).": "Für den Versand gilt die Großhandelsregel dieses Arbeitsbereichs (G1).",
  "Sending is not possible yet: when wholesale stock changes owner and counts as revenue is still an open owner decision.": "Der Versand ist noch gesperrt. Der Inhaber muss festlegen, wann Großhandelsware den Eigentümer wechselt und der Umsatz erfasst wird.",
  "Sending queues this exact email. “Accepted” means the email service took it; delivery is shown when it reports it.": "Mit dem Absenden wird genau diese E-Mail zum Versand vorgemerkt. „Angenommen“ bedeutet, dass der E-Mail-Dienst sie übernommen hat. Die Zustellung erscheint, sobald der Dienst sie meldet.",
  "Sending stock also requires Stock management permission.": "Zum Versand von Ware benötigen Sie zusätzlich Verwaltungsrechte für den Bestand.",
  "Sending…": "Wird gesendet …",
  "Sent": "Gesendet",
  "Sent after this count, not all arrived": "Gesendet nach dieser Zählung, nicht alle angekommen",
  "Sent by account": "Versendet nach Konto",
  "Sent by the customer": "Gesendet vom Kunden",
  "Sent from": "Gesendet von",
  "Sent from your account · the receiving account confirms arrival": "Von Ihrem Konto versandt · das Empfängerkonto bestätigt den Wareneingang",
  "Sent quantities and prices are preserved; use receipt corrections for quantities. New prices apply only to new dispatches.": "Versandte Mengen und Preise bleiben dokumentiert. Mengenkorrekturen erfolgen über den Wareneingang. Neue Preise gelten nur für neue Sendungen.",
  "Sent quantities count toward the request. Missing or damaged items stay in receipt review.": "Gesendete Mengen werden auf die Anfrage angerechnet. Fehlende oder beschädigte Gegenstände bleiben in der Quittungsprüfung.",
  "Sent stock is in transit. Use “Cancel sent shipment” with its physical state.": "Die versandte Ware ist unterwegs. Wählen Sie „Versandte Sendung stornieren“ und geben Sie an, wo sich die Ware tatsächlich befindet.",
  "Sent stock stays in transit. The agent confirms the received quantity; shortages or damage are flagged for admin review. Repeating confirmation must not add stock twice.": "Versandte Ware bleibt bis zur Bestätigung unterwegs. Der Vertriebspartner bestätigt die eingegangene Menge. Fehlmengen und Schäden werden der Administration zur Prüfung gemeldet. Eine wiederholte Bestätigung darf den Bestand nicht doppelt erhöhen.",
  "Sent to agent": "An Vertriebspartner gesendet",
  "Sent units waiting for the agent to confirm receipt. They are neither warehouse availability nor agent sellable stock.": "Einheiten gesendet, die darauf warten, dass der Agent den Empfang bestätigt. Sie sind weder Lagerverfügbarkeit noch Agent verkaufbare Lager.",
  "Sent · awaiting confirmation": "Gesendet · auf Bestätigung warten",
  "Sent · on hold": "Gesendet · im Wartezustand",
  "Separate columns with a tab and rows with a new line.": "Separate Spalten mit einem Tab und Zeilen mit einer neuen Zeile.",
  "Separate from landed stock cost": "Getrennt von den Einstandskosten",
  "Service recovery": "Service-Wiederherstellung",
  "Set an access code before opening the shop.": "Legen Sie einen Zugangscode fest, bevor Sie den Shop öffnen.",
  "Set an amount per product": "Legen Sie einen Betrag pro Produkt fest",
  "Set by Admin O": "Set von Admin O",
  "Set on each account": "Auf jeden Account setzen",
  "Set stock alerts, cost allocation and batch selection defaults. Agents use assigned selling prices. These settings require backend implementation.": "Setzen Sie Bestandsalarmmeldungen, Kostenzuweisungen und Chargenauswahlstandards. Agenten verwenden zugewiesene Verkaufspreise. Diese Einstellungen erfordern eine Backend-Implementierung.",
  "Set terms": "Festgelegte Bedingungen",
  "Set the Own shop terms": "Setzen Sie die eigenen Shop-Bedingungen",
  "Set the rate and profit-based or sales-based agreement on the agent profile. Prepaid wholesale accounts earn no extra commission. Future agreement changes must preserve historical orders.": "Im Vertriebspartnerprofil legen Sie den Provisionssatz und die Berechnungsgrundlage fest: Gewinn oder Umsatz. Großhandelskonten mit Vorkasse erhalten keine zusätzliche Provision. Änderungen der Vereinbarung müssen bestehende Bestellungen unverändert lassen.",
  "Set the workspace name, currency, timezone and date format. These preferences are design controls until connected to the backend.": "Legen Sie den Workspace-Namen, die Währung, die Zeitzone und das Datumsformat fest. Diese Präferenzen sind Design-Steuerelemente, bis sie mit dem Backend verbunden sind.",
  "Set up before selling": "Vor dem Verkauf einrichten",
  "Set up before the Own shop can sell": "Einrichten, bevor der eigene Shop verkaufen kann",
  "Set up two-step sign-in": "Zweistufiges Anmelden einrichten",
  "Settings": "Einstellungen",
  "Settings were changed by someone else. Refresh to see the latest values.": "Einstellungen wurden von jemand anderem geändert. Erfrischen Sie sich, um die neuesten Werte zu sehen.",
  "Settlement": "Abrechnung",
  "Setup key": "Einrichtungsschlüssel",
  "Setup link": "Einrichtungslink",
  "Share": "Teilen",
  "Share PDF": "PDF teilen",
