  "Share an order": "Bestellung teilen",
  "Share in chat": "Im Chat teilen",
  "Share link": "Link teilen",
  "Share order protocols": "Bestellprotokolle teilen",
  "Share protocols and stay in touch in customer chat.": "Teilen sie protokolle und bleiben sie im kundenchat in kontakt.",
  "Share selected PDFs": "Ausgewählte PDFs teilen",
  "Share this order in chat to request a correction.": "Teilen Sie diese Bestellung im Chat, um eine Korrektur anzufordern.",
  "Share your shop": "Shop teilen",
  "Shared / vial": "Anteil je Fläschchen",
  "Shared admin chat": "Gemeinsamer Admin-Chat",
  "Shared by everyone. The ledger stays in EUR; the exchange currency is a dated daily reference only and never converts stored amounts. Timezone sets report day boundaries.": "Diese Einstellungen gelten für alle. Die Buchungswährung ist EUR. Der Tagesreferenzkurs dient nur zur Information und rechnet gespeicherte Beträge nicht um. Die Zeitzone bestimmt, wann ein Berichtstag beginnt und endet.",
  "Shared costs": "Gemeinsame Kosten",
  "Shared preferences are managed by admins with Workspace settings access. Agents cannot change them. In this preview preferences are saved on this browser; production must store and enforce them on the server.": "Gemeinsame Einstellungen werden von Administratoren mit Zugriff auf die Arbeitsbereichseinstellungen verwaltet. Vertriebspartner können sie nicht ändern. In der Vorschau werden sie in diesem Browser gespeichert. Im Produktivbetrieb müssen sie auf dem Server gespeichert und durchgesetzt werden.",
  "Shared stock of": "Geteilter Bestand von",
  "Shared · admin team": "Geteiltes · Admin-Team",
  "Sharing a protocol requires Protocols access.": "Das Teilen eines Protokolls erfordert den Zugriff auf Protokolle.",
  "Sharing did not work in this browser. Use Download instead.": "Das Teilen funktionierte in diesem Browser nicht. Verwenden Sie stattdessen Download.",
  "Sharing was cancelled. Nothing was shared.": "Das Teilen wurde abgesagt. Nichts wurde geteilt.",
