  "Shipped": "Versandt",
  "Shipping": "Versand",
  "Shipping, customs or fees that belong to a purchase go on the purchase (landed cost), not here.": "Versandkosten, Zoll und Gebühren für einen Einkauf werden direkt beim Einkauf als Einstandskosten erfasst.",
  "Shipping, customs, fees — allocated into landed cost, or booked as an expense on the order date": "Versandkosten, Zoll und Gebühren in die Einstandskosten einrechnen oder zum Bestelldatum als Ausgabe buchen",
  "Shop": "Shop",
  "Shop access": "Shop-Zugang",
  "Shop batch": "Shop Batch",
