  "Shop link copied.": "Shop Link kopiert.",
  "Shop listing": "Shop Listing",
  "Shop listing saved. Every agent shop shows it now.": "Shop Listing gespeichert. Jeder Agent Shop zeigt es jetzt.",
  "Shop preview link copied": "Shop Preview Link kopiert",
  "Shop receipt ·": "Eingang des Shops",
  "Shop settings": "Shop-Einstellungen",
  "Shop settings saved in this preview": "Shop-Einstellungen in dieser Vorschau gespeichert",
  "Shop settings saved.": "Shop-Einstellungen gespeichert.",
  "Shop staff share the Own shop stock, orders and conversation. Their sales use the Own shop agreement.": "Shop-Mitarbeiter teilen sich den eigenen Shop-Bestand, Bestellungen und Gespräche. Ihre Verkäufe nutzen den eigenen Shop-Vertrag.",
  "Shop staff use the agent workspace for the shared Own shop account. Their agreement can be commission on profit, a percentage of sales, or prepaid. This invitation does not grant admin access. Supplier-direct shipments do not reduce shop stock.": "Shop-Mitarbeiter nutzen den Vertriebspartnerbereich des gemeinsamen Kontos „Eigener Shop“. Vereinbart werden kann eine Gewinnprovision, eine Umsatzprovision oder Vorkasse. Die Einladung gewährt keine Administrationsrechte. Direktlieferungen von Lieferanten verringern den Shop-Bestand nicht.",
  "Short neutral description customers see": "Kurze neutrale Beschreibung Kunden sehen",
  "Show a shop name to customers": "Zeigen Sie den Kunden einen Shopnamen",
  "Show exact available quantities": "Genaue verfügbare Mengen anzeigen",
  "Show this product in the active catalogue again.": "Zeigen Sie dieses Produkt im aktiven Katalog noch einmal.",
  "Shown": "Eingeblendet",
  "Shown in every agent’s customer shop for this exact variant. Agents cannot change it. Do not add dosing or therapeutic claims.": "Für diese Variante in allen Kundenshops sichtbar. Vertriebspartner können den Text nicht ändern. Keine Dosierungsangaben oder therapeutischen Wirkversprechen hinzufügen.",
  "Sign in": "Anmelden",
  "Sign in again to continue": "Zum Fortfahren erneut anmelden",
