  "Super admins can invite, promote and manage admins. This grants all operational permissions. The original creator remains protected.": "Super-Admins dürfen Administratoren einladen, befördern und verwalten. Die Rolle gewährt alle betrieblichen Berechtigungen. Das ursprüngliche Erstellerkonto bleibt geschützt.",
  "Super admins manage all workspace areas and invite or manage other admins. Admins have full operational access or selected permissions, but cannot manage the team. The original creator cannot be suspended, removed or demoted. Invitations here are a preview; no email is sent.": "Super-Admins verwalten alle Arbeitsbereiche und dürfen Administratoren einladen und verwalten. Administratoren haben vollen betrieblichen Zugriff oder einzelne Rechte, dürfen das Team aber nicht verwalten. Das ursprüngliche Erstellerkonto kann weder gesperrt noch entfernt oder herabgestuft werden. In dieser Vorschau wird zu Einladungen keine E-Mail gesendet.",
