  "Suspend, restore or remove access on each account’s own Access list. A change on one account never changes the others.": "Sperren, reaktivieren oder entfernen Sie Zugänge in der Zugriffsliste des jeweiligen Kontos. Änderungen wirken sich ausschließlich auf dieses Konto aus.",
  "Suspended": "Gesperrt",
  "Suspended · signs out now": "Suspendiert · Jetzt aussteigen",
  "Suspending pauses one person on this account; their history, orders, messages and other accounts are kept, and Restore brings the same access back without a new invitation. Suspending the account pauses everyone on it.": "Die Sperre entzieht einer Person vorübergehend den Zugriff auf dieses Konto. Verlauf, Bestellungen, Nachrichten und andere Konten bleiben erhalten. Eine Reaktivierung stellt denselben Zugriff ohne neue Einladung wieder her. Eine Kontosperre betrifft hingegen alle Personen auf diesem Konto.",
