  "Thank you for your help.": "Vielen Dank für Ihre Hilfe.",
  "Thank you! Could you share the latest Retatrutide protocol with me?": "Vielen Dank! Könnten Sie das neueste Retatrutide-Protokoll mit mir teilen?",
