  "That code does not match. Please try again.": "Der Code stimmt nicht überein. Versuchen Sie es erneut.",
  "That code is not valid. Check your authenticator app and try again.": "Der Code ist ungültig. Prüfen Sie Ihre Authentifizierungs-App und versuchen Sie es erneut.",
