  "This backup is larger than 60 MB.": "Dieses Backup ist größer als 60 MB.",
  "This batch changed since you opened it. Refresh and review again.": "Diese Charge hat sich geändert, seit Sie sie geöffnet haben. Refresh und Review noch einmal.",
  "This batch has already been sold or was not priced in this preview. Review its sales before reducing the receipt.": "Einheiten dieser Charge wurden bereits verkauft oder für diese Charge ist in der Vorschau kein Preis hinterlegt. Prüfen Sie die Verkäufe, bevor Sie den Wareneingang verringern.",
  "This browser cannot share these files directly. Download them, then attach them in your messaging app.": "Dieser Browser kann diese Dateien nicht direkt teilen. Laden Sie sie herunter und fügen Sie sie dann in Ihrer Messaging-App an.",
  "This browser returned an invalid push subscription.": "Dieser Browser hat ein ungültiges Push-Abonnement zurückgegeben.",
  "This browser’s push service is not supported.": "Der Push-Service dieses Browsers wird nicht unterstützt.",
  "This buyer account is not active.": "Dieses Käuferkonto ist nicht aktiv.",
  "This case changed. Refresh and review again.": "Dieser Fall hat sich geändert. Refresh und Review noch einmal.",
  "This case is already closed.": "Dieser Fall ist bereits abgeschlossen.",
  "This conversation belongs to another account.": "Diese Unterhaltung gehört zu einem anderen Konto.",
  "This conversation belongs to another account. Switch account to send here.": "Diese Unterhaltung gehört zu einem anderen Konto. Wechseln Sie das Konto, um hier eine Nachricht zu senden.",
  "This conversation belongs to no account.": "Dieser Unterhaltung ist kein Konto zugeordnet.",
