  "This device": "Diese Vorrichtung",
  "This device could not start background notifications. Reload the page and try again.": "Dieses Gerät konnte keine Hintergrundbenachrichtigungen starten. Laden Sie die Seite neu und versuchen Sie es erneut.",
  "This device is locked and its private data was cleared, but PeptiStock has not confirmed that your session ended. It finishes signing out as soon as the connection returns. Keep this page open, or reopen PeptiStock when you are online.": "Dieses Gerät ist gesperrt. Seine privaten Daten wurden gelöscht. PeptiStock konnte das Ende der Sitzung noch nicht bestätigen. Die Abmeldung wird abgeschlossen, sobald die Verbindung wiederhergestellt ist. Lassen Sie die Seite geöffnet oder öffnen Sie PeptiStock erneut, wenn Sie online sind.",
  "This dispatch is cancelled.": "Dieser Versand wird storniert.",
  "This draft changed (another tab or person saved it). Reload it, then preview again.": "Dieser Entwurf wurde geändert (ein anderer Tab oder eine andere Person hat ihn gespeichert). Laden Sie es erneut und dann erneut eine Vorschau.",
  "This draft changed since you previewed it. Preview the current draft again before publishing.": "Dieser entwurf hat sich geändert, seit sie ihn in der vorschau gesehen haben. Sehen Sie sich den aktuellen Entwurf vor der Veröffentlichung erneut an.",
  "This draft changed. Reload it first.": "Dieser Entwurf hat sich geändert. Laden Sie es zuerst neu.",
  "This draft changed. Review the current draft.": "Dieser Entwurf hat sich geändert. Überprüfen Sie den aktuellen Entwurf.",
  "This draft changed. Review the note against the current draft.": "Dieser Entwurf hat sich geändert. Überprüfen Sie die Notiz gegen den aktuellen Entwurf.",
  "This draft could not be saved. Leave anyway and lose the unsaved changes?": "Der Entwurf konnte nicht gespeichert werden. Trotzdem verlassen und die ungespeicherten Änderungen verwerfen?",
  "This draft was changed elsewhere. Reload it before saving again.": "Dieser Entwurf wurde an anderer Stelle geändert. Laden Sie es wieder auf, bevor Sie es erneut speichern.",
  "This draft was saved elsewhere (another tab or admin). Your text is still on screen: copy what you need, then reload the draft.": "Dieser Entwurf wurde an anderer Stelle gespeichert (ein weiterer Tab oder Admin). Ihr Text ist immer noch auf dem Bildschirm: Kopieren Sie, was Sie brauchen, und laden Sie dann den Entwurf neu.",
  "This draft was saved elsewhere (another tab or admin). Your text is still on this screen: copy what you need, then reload the draft. Nothing was overwritten.": "Dieser Entwurf wurde an anderer Stelle gespeichert (ein weiterer Tab oder Admin). Ihr Text befindet sich immer noch auf diesem Bildschirm: Kopieren Sie, was Sie brauchen, und laden Sie dann den Entwurf neu. Nichts wurde überschrieben.",
  "This email already has an invitation or admin account.": "Für diese E-Mail-Adresse besteht bereits eine Einladung oder ein Administratorkonto.",
  "This email was already queued for sending and cannot be cancelled here.": "Diese E-Mail ist bereits zum Versand vorgemerkt und kann hier nicht mehr storniert werden.",
  "This email was cancelled. Prepare a new one.": "Diese E-Mail wurde storniert. Bereiten Sie eine neue E-Mail vor.",
  "This exact name and strength already exists (": "Dieser genaue Name und diese Stärke existieren bereits ()",
  "This exact name and strength already exists. Cancel and select it from the product list.": "Dieser genaue Name und diese Stärke gibt es bereits. Abbrechen und aus der Produktliste auswählen.",
  "This exceeds the unshipped request quantity. Reduce it or create a separate shipment.": "Dies übersteigt die nicht versendete Anfragemenge. Reduzieren Sie es oder erstellen Sie eine separate Sendung.",
  "This expense is a fee of a purchase. It is reversed by cancelling that purchase.": "Diese Kosten sind eine Gebühr für einen Kauf. Es wird umgekehrt, indem dieser Kauf storniert wird.",
  "This figure is shown with sample data for design review.": "Diese Zahl wird mit Beispieldaten für die Design-Überprüfung gezeigt.",
  "This file cannot be used. Choose another file.": "Diese Datei kann nicht verwendet werden. Wählen Sie eine andere Datei.",
  "This file did not pass the virus check. Choose another file.": "Die Datei hat die Virenprüfung nicht bestanden. Wählen Sie eine andere Datei.",
  "This file is already a protocol version.": "Diese Datei ist bereits eine Protokollversion.",
  "This file is already attached, so it is kept with that record.": "Diese Datei ist bereits angehängt und bleibt dem zugehörigen Eintrag zugeordnet.",
  "This file is already in a conversation. Forward that message to share it again.": "Die Datei wurde bereits in einer Unterhaltung verwendet. Leiten Sie die betreffende Nachricht weiter, um sie erneut zu teilen.",
  "This file is empty.": "Diese Datei ist leer.",
  "This file is no longer available. Upload it again.": "Diese Datei ist nicht mehr verfügbar. Laden Sie es noch einmal hoch.",
