  "This record is not in this account": "Dieser Datensatz ist nicht in diesem Konto",
  "This record is part of the permanent history and cannot be changed.": "Dieser Eintrag gehört zum dauerhaften Verlauf und kann nicht geändert werden.",
  "This removes the German edition from the library, sharing and chats. English stays available. The German draft and release evidence are kept.": "Dadurch wird die deutsche Ausgabe aus der Bibliothek, dem Teilen und Chats entfernt. Englisch bleibt verfügbar. Der deutsche Entwurf und die Veröffentlichungsbeweise werden aufbewahrt.",
  "This replaces the published protocol for this product (v": "Dies ersetzt das veröffentlichte Protokoll für dieses Produkt (v)",
  "This request": "Diese Anfrage",
