  "This version is a PDF-only upload. It has no editable text to restore; download the PDF instead.": "Diese Version wurde nur als PDF hochgeladen. Sie enthält keinen bearbeitbaren Text, der wiederhergestellt werden könnte. Laden Sie das PDF herunter.",
