  "Two-step sign-in cannot be set up on this server yet. The server encryption key is not configured.": "Die Zwei-Schritt-Anmeldung kann auf diesem Server noch nicht eingerichtet werden. Der Verschlüsselungsschlüssel des Servers ist nicht konfiguriert.",
