  "Two-step sign-in is required for administrators, but this server cannot set it up yet. Contact the workspace owner.": "Für Administratoren ist eine Zwei-Schritt-Anmeldung erforderlich, die auf diesem Server noch nicht eingerichtet werden kann. Kontaktieren Sie den Inhaber des Arbeitsbereichs.",
  "Two-step sign-in must be set up first. Use \"Sign in as someone else\" to go to the sign-in page.": "Richten Sie zuerst die Zwei-Schritt-Anmeldung ein. Wählen Sie „Als andere Person anmelden“, um zur Anmeldung zu gelangen.",
