  "Type CLEAR to confirm.": "Typ CLEAR zur Bestätigung.",
  "Type DELETE EXISTING to include messages sent before activation.": "Geben Sie DELETE EXISTING ein, um Nachrichten aus der Zeit vor der Aktivierung einzubeziehen.",
