  "Type the exact strength and unit. A new variant starts with zero stock.": "Geben Sie die genaue Stärke und Einheit ein. Eine neue Variante beginnt mit Bestand null.",
  "UI preview only. No server cleanup job is connected. Downloaded files and external copies cannot be recalled.": "Reine Oberflächenvorschau. Es ist kein serverseitiger Löschvorgang angebunden. Heruntergeladene Dateien und externe Kopien können nicht zurückgerufen werden.",
  "UI preview only. This clears sample history for this tab; reload restores it. Permanent server deletion is not connected.": "Reine Oberflächenvorschau. Der Beispielverlauf wird nur in diesem Tab geleert und beim Neuladen wiederhergestellt. Eine dauerhafte Löschung auf dem Server ist nicht angebunden.",
