  "Units": "Einheiten",
  "Units already missing at the count may have been booked into this shipment and be part of its shortage. Decline this report if the shipment's shortage covers it, or enter the adjustment you can prove with your evidence.": "Bereits bei der Zählung fehlende Einheiten könnten dieser Sendung zugebucht worden und in deren Fehlmenge enthalten sein. Lehnen Sie die Meldung ab, wenn die Fehlmenge der Sendung die Abweichung bereits abdeckt. Andernfalls buchen Sie nur eine belegbare Korrektur.",
  "Units already sold or reserved for a draft cannot be taken back; correct those orders or drafts first. Sold units keep their cost. Units that did not arrive go back to review. The account's own receipt stays as it was; this correction is recorded next to it.": "Verkaufte oder für einen Entwurf reservierte Einheiten lassen sich nicht zurückbuchen. Korrigieren Sie zuerst die betreffenden Bestellungen oder Entwürfe. Verkaufte Einheiten behalten ihre Einstandskosten. Nicht eingegangene Einheiten gehen erneut in Prüfung. Der ursprüngliche Eingangsbeleg des Kontos bleibt erhalten. Die Korrektur wird daneben dokumentiert.",
  "Units currently usable and ready to sell. Stock waiting for receipt confirmation is not included.": "Verwendbare, verkaufsbereite Einheiten. Ware mit noch ausstehender Eingangsbestätigung ist ausgenommen.",
  "Units leaving stock": "Lagerabgang in Einheiten",
  "Units of this purchase were already sent. A sent purchase cannot be cancelled.": "Einheiten aus diesem Einkauf wurden bereits versandt. Der Einkauf kann nicht mehr storniert werden.",
  "Units requested": "Angeforderte Einheiten",
  "Units reserved for sending cannot be removed.": "Für den Versand reservierte Einheiten können nicht entfernt werden.",
  "Units that arrived damaged. These remain in the receipt history and are not available to sell.": "Beschädigt eingegangene Einheiten bleiben im Wareneingangsverlauf dokumentiert und sind nicht zum Verkauf verfügbar.",
  "Units were already received; use a correction instead.": "Es wurden bereits Einheiten empfangen. Erfassen Sie eine Korrektur.",
  "Units you counted": "Einheiten, die Sie gezählt haben",
