  "Unsold quantity × current selling price. This is potential future revenue, not cash, realized profit or guaranteed income.": "Unverkaufte Menge × aktueller Verkaufspreis. Das ist ein möglicher künftiger Umsatz. Es handelt sich weder um einen Zahlungseingang noch um realisierten Gewinn oder garantierte Einnahmen.",
