  "Updated in this preview.": "Aktualisiert in dieser Preview.",
  "Updates": "Aktualisierungen",
  "Updates that need your action always appear under the bell. Chat messages keep their own unread badge in Messages and never fill the bell. Push sends a short title only; details open in PeptiStock.": "Handlungsbedarf wird immer unter der Glocke angezeigt. Ungelesene Chatnachrichten haben unter „Nachrichten“ einen eigenen Zähler und erscheinen nicht unter der Glocke. Push-Mitteilungen enthalten nur einen kurzen Titel. Details öffnen sich in PeptiStock.",
  "Upload PDF": "PDF hochladen",
  "Upload an unlocked PDF so agents can open it.": "Laden Sie ein entsperrtes PDF hoch, damit Agenten es öffnen können.",
  "Upload or replace protocol": "Hochladen oder Ersetzen des Protokolls",
  "Upload protocol": "Upload-Protokoll",
