  "Upload the file for this record first.": "Laden Sie zuerst die Datei für diesen Datensatz hoch.",
  "Usable received": "Verwendbar eingegangen",
  "Usable stock does not change. No replacement, refund or financial loss is recorded automatically — loss recognition stays a separate, gated decision.": "Der verwendbare Warenbestand bleibt unverändert. Es werden weder Ersatz noch Rückerstattung oder finanzieller Verlust automatisch gebucht. Die Anerkennung eines Verlusts ist eine separate Entscheidung mit eigener Freigabe.",
  "Usable stock physically received into the warehouse, less dispatched units. A purchase order alone does not add available stock.": "Tatsächlich im Lager eingegangene, verwendbare Ware abzüglich bereits versandter Einheiten. Eine Bestellung allein erhöht den verfügbaren Bestand nicht.",
  "Usable units confirmed received by agents. Sent stock is excluded until receipt confirmation.": "Von Agenten bestätigte verwendbare Einheiten. Gesendete Bestände sind bis zur Empfangsbestätigung ausgeschlossen.",
  "Usable units currently available to sell. Stock on the way is excluded until receipt is confirmed.": "Derzeit verfügbare nutzbare Einheiten. Lager auf dem Weg ist ausgeschlossen, bis der Empfang bestätigt wird.",
  "Use 4–40 letters, numbers or dashes.": "Verwenden Sie 4–40 Buchstaben, Zahlen oder Bindestriche.",
  "Use Create shipment to add this product.": "Verwenden Sie Create Shipment, um dieses Produkt hinzuzufügen.",
  "Use a 3-letter currency code.": "Verwenden sie einen 3-buchstaben-währungscode.",
  "Use a password of at least 10 characters.": "Verwenden Sie ein Passwort von mindestens 10 Zeichen.",
  "Use a recovery code": "Verwenden Sie einen Recovery-Code",
  "Use a valid received date between the sent date and today.": "Verwenden Sie ein gültiges empfangenes Datum zwischen dem gesendeten Datum und heute.",
  "Use a valid transfer date on or after the included sales and no later than today.": "Verwenden Sie ein gültiges Überweisungsdatum am oder nach den inbegriffenen Verkäufen und spätestens heute.",
  "Use a whole quantity between 0 and": "Geben Sie eine ganze Zahl zwischen 0 und",
  "Use at most": "höchstens zu verwenden",
  "Use authenticator code": "Verwenden des Authentifikationscodes",
  "Use distinct products and whole quantities.": "Verwenden Sie verschiedene Produkte und ganze Mengen.",
  "Use distinct products, whole quantities and valid landed costs / selling prices.": "Wählen Sie unterschiedliche Produkte und geben Sie ganzzahlige Mengen sowie gültige Einstandskosten und Verkaufspreise ein.",
  "Use illustration": "Verwendungshinweis",
  "Use no more than 500 sections in one protocol.": "Verwenden Sie nicht mehr als 500 Abschnitte in einem Protokoll.",
  "Use only when the shipment has not left or has been returned. Shop stock will become available again; supplier-direct units return to the order allocation.": "Nur verwenden, wenn die Ware noch nicht versandt wurde oder tatsächlich zurückgekommen ist. Ware aus dem Shop wird wieder verfügbar. Direktlieferungen vom Lieferanten werden der Bestellmenge wieder zugeordnet.",
  "Use receipt corrections after dispatch.": "Verwenden Sie Quittungskorrekturen nach dem Versand.",
  "Use the cost builder to record shipping, customs or fee charges.": "Verwenden Sie den Cost Builder, um Versand-, Zoll- oder Gebührengebühren aufzuzeichnen.",
  "Use the landed cost recorded on the linked purchase.": "Verwenden Sie die Einstandskosten aus dem verknüpften Einkauf.",
  "Use these product quantities and recipient details when contacting your supplier. No message is sent automatically.": "Verwenden Sie diese Produktmengen und Empfängerdaten, wenn Sie Ihren Lieferanten kontaktieren. Es wird keine automatische Nachricht gesendet.",
  "Use up to 500 sections.": "Verwenden Sie bis zu 500 Abschnitte.",
  "Use whole quantities between 1 and 100,000.": "Verwenden Sie ganze Mengen zwischen 1 und 100.000.",
  "Use whole quantities of at least 1 (remove a line instead of 0).": "Verwenden Sie ganze Mengen von mindestens 1 (entfernen Sie eine Zeile anstelle von 0).",
  "Use whole quantities of at least 1.": "Geben Sie eine ganze Zahl ab 1 ein.",
  "Use whole quantities.": "Geben Sie die Mengen als ganze Zahlen ein.",
  "Used for this email only. The order and customer details are not changed.": "Wird nur für diese E-Mail verwendet. Die Bestell- und Kundendaten werden nicht geändert.",
