  "View PDF": "PDF ansehen",
  "View agent profiles, or manage their accounts and agreements. This does not grant access to the admin team.": "Zeigen Sie Agentenprofile an oder verwalten Sie deren Konten und Vereinbarungen. Dies gewährt keinen Zugriff auf das Admin-Team.",
  "View all": "Alle anzeigen",
  "View as account (read-only)": "Kontoansicht öffnen (schreibgeschützt)",
  "View as agent": "Ansicht als Vertriebspartner",
  "View breakdown": "Aufstellung anzeigen",
  "View business expenses, or add and correct expense records.": "Anzeigen von Geschäftsausgaben oder Hinzufügen und Korrigieren von Kostenaufzeichnungen.",
  "View business totals and sales trends.": "Sehen Sie sich die Geschäftssummen und Umsatztrends an.",
  "View business-wide changes and who made them. Entries may include financial details.": "Sehen Sie sich unternehmensweite Veränderungen an und wer sie vorgenommen hat. Die Einträge können finanzielle Angaben enthalten.",
  "View business-wide revenue, costs, commissions and performance. This reveals financial information even without access to transaction pages.": "Sehen Sie unternehmensweite Einnahmen, Kosten, Provisionen und Leistung. Dies zeigt Finanzinformationen auch ohne Zugriff auf Transaktionsseiten.",
  "View costs": "Kosten anzeigen",
  "View delivery": "Lieferung anzeigen",
