  "Wholesale sales are for prepaid buyer accounts. Agents and the own shop receive business stock through shipments.": "Großhandelsverkäufe sind für Käuferkonten mit Vorkasse vorgesehen. Vertriebspartner und der eigene Shop erhalten Unternehmensware über Sendungen.",
