  "You": "Sie",
  "You already have access to this workspace.": "Sie haben bereits Zugriff auf diesen Arbeitsbereich.",
  "You are now signed in to a different workspace.": "Sie sind jetzt in einem anderen Arbeitsbereich angemeldet.",
  "You are offline. Changes cannot be sent until the connection returns; your drafts stay on this screen.": "Sie sind offline. Änderungen können erst nach Wiederherstellung der Verbindung gesendet werden. Ihre Entwürfe bleiben auf diesem Bildschirm erhalten.",
  "You can arrange products only for an account you belong to.": "Sie können Produkte nur für Konten sortieren, denen Sie angehören.",
  "You can only reply to a message in this conversation.": "Sie können nur auf Nachrichten in dieser Unterhaltung antworten.",
  "You can read this conversation but not change it.": "Sie können diese Unterhaltung lesen, aber nicht bearbeiten.",
  "You can read this conversation but not send messages.": "Sie können diese Unterhaltung lesen, aber keine Nachrichten senden.",
  "You cannot attach files here.": "Hier können Sie keine Dateien anhängen.",
  "You cannot change your own access.": "Sie können Ihren eigenen Zugang nicht ändern.",
  "You cannot forward to this conversation.": "Sie dürfen keine Nachrichten an diese Unterhaltung weiterleiten.",
  "You cannot remove your own Super admin access.": "Sie können Ihre eigenen Super-Admin-Rechte nicht entziehen.",
  "You cannot suspend or revoke your own access.": "Sie können Ihren eigenen Zugriff weder sperren noch widerrufen.",
  "You do not have permission to change workspace settings.": "Sie haben keine Berechtigung zum Ändern der Arbeitsbereichseinstellungen.",
  "You do not have permission to clear this conversation.": "Sie haben keine Berechtigung, den Verlauf dieser Unterhaltung zu löschen.",
  "You have unsaved work on this screen (for example an open sale or form). Reloading now loses it. Reload anyway?": "Sie haben auf diesem Bildschirm nicht gespeicherte Arbeit (z. B. einen offenen Verkauf oder ein Formular). Reloading verliert es jetzt. Reload sowieso?",
  "You keep": "Sie behalten",
  "You keep · commission": "Sie behalten · Kommission",
  "You no longer have access to the account these entries were for.": "Sie haben keinen Zugriff mehr auf das Konto, zu dem diese Eingaben gehören.",
  "You seem to be offline. Your message is kept; try again when you are back online.": "Sie scheinen offline zu sein. Ihre nachricht bleibt erhalten; versuchen sie es erneut, wenn sie wieder online sind.",
  "You send the business": "Sie überweisen an das Unternehmen",
  "You stay signed in. Agents are not affected.": "Sie bleiben angemeldet. Vertriebspartnerkonten sind nicht betroffen.",
  "You will see Admin O’s decision here. This is a sample request.": "Sie werden die Entscheidung von Admin O hier sehen. Dies ist eine Sample Request.",
  "You will see the exact email before it is sent. Delivery status appears here once the email service reports it.": "Vor dem Versand sehen Sie den genauen Inhalt der E-Mail. Der Zustellstatus erscheint hier, sobald der E-Mail-Dienst ihn meldet.",
  "Your access changed since this request was sent. Refresh to see the current state.": "Ihre Berechtigungen haben sich seit dem Absenden der Anfrage geändert. Aktualisieren Sie die Seite, um den aktuellen Stand zu sehen.",
  "Your access changed while a sale was being saved. Check the orders before entering it again.": "Ihre Berechtigungen haben sich beim Speichern des Verkaufs geändert. Prüfen Sie die Bestellliste, bevor Sie den Verkauf erneut erfassen.",
  "Your access changed while this sale was being saved. It may already be recorded — check the list of orders before entering it again.": "Ihre Berechtigungen haben sich beim Speichern dieses Verkaufs geändert. Der Verkauf könnte bereits erfasst sein. Prüfen Sie die Bestellliste, bevor Sie ihn erneut eingeben.",
  "Your access changed while you were signed out.": "Ihre Berechtigungen haben sich während Ihrer Abmeldung geändert.",
  "Your access changed. Now working in": "Ihr Zugang hat sich geändert. Jetzt arbeiten in",
  "Your access changed: clearing chat history needs Messages management and Workspace settings management.": "Ihre Berechtigungen haben sich geändert. Zum Löschen des Chatverlaufs benötigen Sie Verwaltungsrechte für Nachrichten und für die Arbeitsbereichseinstellungen.",
  "Your access changed: deleting a message needs Messages management.": "Ihre Berechtigungen haben sich geändert. Zum Löschen einer Nachricht benötigen Sie Verwaltungsrechte für Nachrichten.",
  "Your access does not include Messages.": "Sie haben keinen Zugriff auf Nachrichten.",
  "Your access is not active. Contact an administrator.": "Ihr Zugang ist nicht aktiv. Wenden Sie sich an die Administration.",
