  "Your account does not have access to these settings.": "Dieses Konto hat keinen Zugriff auf diese Einstellungen.",
  "Your admin team is here to help.": "Ihr Admin-Team ist hier, um zu helfen.",
  "Your agent": "Ihr Vertriebspartner",
